import{G as e,W as t,n,rt as r}from"./chunks/framework.CMPLvzN_.js";var i=JSON.parse(`{"title":"图形找规律","description":"","frontmatter":{},"headers":[],"relativePath":"判断推理/图形推理/index.md","filePath":"判断推理/图形推理/index.md"}`),a={name:`判断推理/图形推理/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="图形找规律" tabindex="-1">图形找规律 <a class="header-anchor" href="#图形找规律" aria-label="Permalink to “图形找规律”">​</a></h1><p>技巧：点、线、面、角</p><h2 id="一笔画图形题" tabindex="-1">一笔画图形题 <a class="header-anchor" href="#一笔画图形题" aria-label="Permalink to “一笔画图形题”">​</a></h2><ol><li>题目中会出现“日”，“田”，“五环奥迪”，“☆”的变形。“<em>田</em>”字是两笔画类型</li><li>图形线条多且杂乱</li></ol><h3 id="捏球法判断一笔画" tabindex="-1">捏球法判断一笔画 <a class="header-anchor" href="#捏球法判断一笔画" aria-label="Permalink to “捏球法判断一笔画”">​</a></h3><p>在图中从大到小圈出所有封闭图形（边不重合），然后看未圈出来的形状是否可以一笔画完，如果可以一笔画完，那这个图形就是一笔画。</p><h2 id="找角" tabindex="-1">找角 <a class="header-anchor" href="#找角" aria-label="Permalink to “找角”">​</a></h2><p>规律包括<strong>数量</strong>与<strong>性质</strong>。</p><p>数量没有规律时考虑性质</p><p>角的规律包括锐角、直角、钝角。</p><p>出现<strong>锯齿状</strong>大概率会是找角，并且是找<strong>锐角</strong>的数量。</p><p>出现<strong>十字交叉</strong>大概率是找<strong>直角</strong>的数量。</p><h2 id="点" tabindex="-1">点 <a class="header-anchor" href="#点" aria-label="Permalink to “点”">​</a></h2><p>主要考察交点数量 需要注意直线与直线、直线与曲线、曲线与曲线的交点数量</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};